  "codebook": {
    "definition": "Credit-claiming is defined as acting in a way to generate the belief that a legislator is personally responsible for causing the government to do something that the constituents like, specifically bringing back particularized benefits (such as federal grants, local projects, targeted legislative provisions, or favorable executive decisions) to their state or target group.",
    "clarification": "To classify a press release as credit-claiming (1), the document must show that the senator is asserting a personal or collaborative role (e.g., 'I secured', 'we fought for', 'through my bill') in achieving a completed positive outcome. Positive outcomes include secured federal grants, passed bills, approved amendments, completed local projects, or successful executive decisions. Announcing federal grants flowing to the home state is classified as credit-claiming if the senator associates themselves with the funding delivery or highlights their role in authorizing the program.",
    "positive_examples": [
      {
        "document_id": "2318",
        "explanation": "The senator explicitly states 'I helped secure an expedited environmental review... and facilitated the return of the project,' taking personal credit for a specific constituency benefit."
      },
      {
        "document_id": "1747",
        "explanation": "The text highlights legislation authored by the senator that was approved by the Senate, taking credit for both past creation of the program and current funding increases."
      },
      {
        "document_id": "2697",
        "explanation": "Senator Inouye explicitly claims credit for bypassing a denied request and successfully finding an alternative federal funding source for his state."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming (0) if the senator is merely advocating for a policy, introducing a bill that has not passed, expressing condolences, taking a position on national debates, or criticizing the administration. Pure position-taking, letters requesting action without a confirmed positive response, and committee hearings without a declared successful result do not count as credit-claiming.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "This text is pure position-taking and partisan criticism regarding port security policy, with no claim of personal positive achievement."
      },
      {
        "document_id": "4531",
        "explanation": "The senators are announcing the introduction of a bill. Since the bill has not yet passed, this represents position-taking and advertising, not a finalized outcome."
      },
      {
        "document_id": "1177",
        "explanation": "The senators are urging the Air Force to act and planning future legislation, representing ongoing advocacy and pressure rather than a successfully achieved outcome."
      }
    ]
  }
}
